  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made individual superconducting circuits controllable quantum optical systems and established a major route to quantum information processing. Its conceptual and experimental influence is exceptional.",
        "attribution": "Blais developed the central theoretical framework; Wallraff and Schoelkopf led landmark experiments and helped establish the field. The three contributions are complementary, though many groups extended the platform.",
        "maturity": "The field has decades of experimental validation and has enabled increasingly capable processors and fundamental studies. The core discovery is mature even as useful fault-tolerant computing remains ahead.",
        "uncertainties": [
          "The 2025 prize recognized foundational superconducting-circuit work, which may affect timing and how this later contribution is distinguished.",
          "The field's broad collaborative history makes the boundary of the central originating contributions contestable."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite decoherence and supplied the conceptual basis for scalable fault-tolerant quantum computing.",
        "attribution": "Shor and Steane introduced influential error-correcting codes, while Kitaev developed topological codes and a powerful framework for fault tolerance. These are distinct, foundational contributions.",
        "maturity": "The theory is established and its principles have been implemented in increasingly capable experiments, although large-scale fault-tolerant operation is not yet routine.",
        "uncertainties": [
          "The broad label combines several related discoveries, and the most appropriate boundary of the credited contribution is debatable."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and observation of quantum spin Hall and topological insulating phases opened a major field linking topology with measurable electronic transport.",
        "attribution": "Kane and Mele established key theoretical predictions, and Molenkamp's experiments provided an early compelling demonstration. Later materials and experiments broadened the field substantially.",
        "maturity": "The underlying topological concepts and experimental signatures are well established, with many further phases and platforms identified.",
        "uncertainties": [
          "The long and distributed development of topological matter makes it difficult to delimit this discovery from adjacent advances."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade arrays turned neutral atoms into a flexible, controllable platform for quantum simulation and computation, enabling new many-body experiments.",
        "attribution": "Browaeys and Lukin groups demonstrated and developed key array experiments, while Saffman contributed foundational neutral-atom gate and platform advances. The field is international and contributions extend beyond these names.",
        "maturity": "The platform has produced robust, reproducible experiments and rapid progress, but its broad scientific legacy and long-term standing are still developing.",
        "uncertainties": [
          "The relative weight of foundational gate proposals, early demonstrations, and later large-array experiments remains unsettled."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Tilman Esslinger"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made strongly interacting lattice models experimentally controllable and enabled landmark quantum simulation of condensed-matter phenomena.",
        "attribution": "Bloch, Greiner, and Esslinger led influential experimental demonstrations and complementary advances. Cirac and Zoller supplied important theoretical foundations, so the proposed experimental emphasis does not exhaust the intellectual credit.",
        "maturity": "The platform and its core results are mature, replicated, and central to modern quantum many-body physics.",
        "uncertainties": [
          "The candidate discovery spans a broad program with substantial theoretical and experimental contributions that do not fit neatly within three laureates."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light enables measurements beyond the conventional shot-noise limit and has become an important tool in precision interferometry, including gravitational-wave detection.",
        "attribution": "Caves established the quantum measurement rationale; Kimble advanced experimental squeezed-light optics, and Mavalvala helped bring the method into gravitational-wave interferometers. The work is a sustained collaboration across theory and experiment.",
        "maturity": "The technique is experimentally established and in operational use, with continuing development and measurable impact.",
        "uncertainties": [
          "The credit spans foundational proposals, laboratory demonstrations, and later instrument deployment across many contributors."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B055",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and enable tests of fundamental physics with unprecedented control and accuracy.",
        "attribution": "Katori introduced the optical lattice clock concept and its key operating principle; Ye drove major experimental development and precision demonstrations. Their complementary contributions are clear.",
        "maturity": "The clocks have been validated across laboratories and reached a level where systematic effects and comparisons are rigorously controlled.",
        "uncertainties": [
          "The broader clock field has many important contributors, though the central conceptual and experimental roles here are strong."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Edward Witten",
        "Juan Maldacena"
      ],
      "assessment": {
        "nobel_worthiness": "AdS/CFT is a remarkable theoretical duality that reshaped quantum field theory, gravity, and the study of strongly coupled systems.",
        "attribution": "Maldacena formulated the duality; Witten developed and clarified its implications, while Polyakov's earlier work helped establish important conceptual groundwork. The proposed pair captures the central formulation and its development.",
        "maturity": "The duality is a durable and extensively used theoretical framework, but direct empirical confirmation in nature remains absent.",
        "uncertainties": [
          "Its domain of application and relationship to realistic quantum gravity remain open.",
          "Theoretical importance is exceptionally high, but the absence of direct experimental tests limits the strength of a physics-prize case."
        ]
      }
    }
  ]
}
